#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    char *endptr;
    long shift = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("USAGE");
        return 0;
    }
    /* Normalize shift to the range 0-25 */
    shift = ((shift % 26) + 26) % 26;

    const char *text = argv[2];
    size_t len = strlen(text);
    if (len > 1024) {
        puts("USAGE");
        return 0;
    }

    for (size_t i = 0; i < len; ++i) {
        char c = text[i];
        if (c >= 'A' && c <= 'Z') {
            c = (char)((c - 'A' + shift) % 26 + 'A');
        } else if (c >= 'a' && c <= 'z') {
            c = (char)((c - 'a' + shift) % 26 + 'a');
        }
        putchar(c);
    }
    putchar('\n');
    return 0;
}
